code.source:
#include <iostream>
using namespace std;

class Counter {
    int count_ = 0;

public:
    Counter& add(int n) {
        count_ += n;
        return *this;
    }
    int get() const { return count_; }
};

int main() {
    Counter c;
    c.add(2).add(3).add(10);
    cout << c.get() << endl;
    return 0;
}

#include <iostream>
using namespace std;

class Counter {
    int count_ = 7;

public:
    void increment() { count_++; }
    int get() const { return count_; }
};

int main() {
    const Counter c;
    cout << c.get() << endl;
    return 0;
}

